1693.     pub open spec fn next_step(self, s: ClusterState, s_prime: ClusterState, step: Step) -> bool {
1694.         match step {
1695.             Step::APIServerStep(input) => self.api_server_next().forward(input)(s, s_prime),
1696.             Step::BuiltinControllersStep(input) => self.builtin_controllers_next().forward(input)(s, s_prime),
1697.             Step::ControllerStep(input) => self.controller_next().forward(input)(s, s_prime),
1698.             Step::ScheduleControllerReconcileStep(input) => self.schedule_controller_reconcile().forward(input)(s, s_prime),
1699.             Step::RestartControllerStep(input) => self.restart_controller().forward(input)(s, s_prime),
1700.             Step::DisableCrashStep(input) => self.disable_crash().forward(input)(s, s_prime),
1701.             Step::DropReqStep(input) => self.drop_req().forward(input)(s, s_prime),
1702.             Step::DisableReqDropStep => self.disable_req_drop().forward(())(s, s_prime),
1703.             Step::PodMonkeyStep(input) => self.pod_monkey_next().forward(input)(s, s_prime),
1704.             Step::DisablePodMonkeyStep => self.disable_pod_monkey().forward(())(s, s_prime),
1705.             Step::ExternalStep(input) => self.external_next().forward(input)(s, s_prime),
1706.             Step::StutterStep => self.stutter().forward(())(s, s_prime),
1707.         }
1708.     }
