1721. 
1722.             (host_result, network_result)
1723.         };
1724.         Action {
1725.             precondition: |input: Option<Message>, s: ClusterState| {
1726.                 &&& received_msg_destined_for(input, HostId::APIServer)
1727.                 &&& result(input, s).0.is_Enabled()
1728.                 &&& result(input, s).1.is_Enabled()
1729.             },
1730.             transition: |input: Option<Message>, s: ClusterState| {
1731.                 let (host_result, network_result) = result(input, s);
1732.                 (ClusterState {
1733.                     api_server: host_result.get_Enabled_0(),
1734.                     network: network_result.get_Enabled_0(),
1735.                     ..s
1736.                 }, ())
1737.             },
1738.         }
1739.     }
