3568. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3569.     recommends
3570.         msg.content.is_get_then_update_request(),
3571. {
3572.     let req = msg.content.get_get_then_update_request();
3573.     // Step 1: get the object
3574.     let get_req = GetRequest {
3575.         key: req.key()
3576.     };
3577.     let get_resp = handle_get_request(get_req, s);
3578.     match get_resp.res {
3579.         Ok(_) => {
3580.             let current_obj = s.resources[req.key()];
3581.             // Step 2: if the object exists, perform a check using a predicate on object
3582.             // The predicate: Is the current object owned by req.owner_ref?
3583.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3584.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3585.                 // Step 3: if the check passes, overwrite the object with the new one
3586.                 // Note that resource_version and uid comes from the current object to avoid conflict error
3587.                 let new_obj = DynamicObjectView {
3588.                     metadata: ObjectMetaView {
3589.                         resource_version: current_obj.metadata.resource_version,
