3591.                         ..req.obj.metadata
3592.                     },
3593.                     ..req.obj
3594.                 };
3595.                 let update_req = UpdateRequest {
3596.                     name: req.name,
3597.                     namespace: req.namespace,
3598.                     obj: new_obj,
3599.                 };
3600.                 let (s_prime, update_resp) = handle_update_request(installed_types, update_req, s);
3601.                 (s_prime, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: update_resp.res}))
3602.             } else {
3603.                 (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(APIError::TransactionAbort)}))
3604.             }
3605.         }
3606.         Err(err) => (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(err)}))
3607.     }
3608. }
