1655.     pub open spec fn init(self) -> StatePred<ClusterState> {
1656.         |s: ClusterState| {
1657.             // The API server is initialized...
1658.             &&& (api_server(self.installed_types).init)(s.api_server)
1659.             // and the built-in controllers are initialized...
1660.             &&& (builtin_controllers().init)(())
1661.             // and the network is initialized...
1662.             &&& (network().init)(s.network)
1663.             // and message drop is enabled...
1664.             &&& s.req_drop_enabled
1665.             // and pod monkey is enabled...
1666.             &&& s.pod_monkey_enabled
1667.             // and for each controller...
1668.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1669.                 ==> {
1670.                     let model = self.controller_models[key];
1671.                     // its internal state exists...
1672.                     &&& s.controller_and_externals.contains_key(key)
1673.                     // and is initialized...
1674.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1675.                     // and crash for this controller is enabled...
1676.                     &&& s.controller_and_externals[key].crash_enabled
1677.                     // and if the controller has an associated external system...
1678.                     &&& model.external_model is Some
1679.                         ==> {
1680.                             // the internal state of that external system exists...
1681.                             &&& s.controller_and_externals[key].external is Some
1682.                             // and is initialized.
1683.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
1684.                         }
1685.                 }
1686.         }
1687.     }
