1710.     pub open spec fn api_server_next(self) -> Action<ClusterState, Option<Message>, ()> {
1711.         let result = |input: Option<Message>, s: ClusterState| {
1712.             let host_result = self.api_server().next_result(
1713.                 APIServerActionInput{ recv: input },
1714.                 s.api_server
1715.             );
1716.             let msg_ops = MessageOps {
1717.                 recv: input,
1718.                 send: host_result.get_Enabled_1().send,
1719.             };
1720.             let network_result = network().next_result(msg_ops, s.network);
1721. 
1722.             (host_result, network_result)
1723.         };
1724.         Action {
1725.             precondition: |input: Option<Message>, s: ClusterState| {
1726.                 &&& received_msg_destined_for(input, HostId::APIServer)
1727.                 &&& result(input, s).0.is_Enabled()
1728.                 &&& result(input, s).1.is_Enabled()
1729.             },
1730.             transition: |input: Option<Message>, s: ClusterState| {
1731.                 let (host_result, network_result) = result(input, s);
1732.                 (ClusterState {
1733.                     api_server: host_result.get_Enabled_0(),
1734.                     network: network_result.get_Enabled_0(),
1735.                     ..s
1736.                 }, ())
1737.             },
1738.         }
1739.     }
