1741.     pub open spec fn builtin_controllers_next(self) -> Action<ClusterState, (BuiltinControllerChoice, ObjectRef), ()> {
1742.         let result = |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1743.             let host_result = self.builtin_controllers().next_result(
1744.                 BuiltinControllersActionInput {
1745.                     choice: input.0,
1746.                     key: input.1,
1747.                     rpc_id_allocator: s.rpc_id_allocator,
1748.                     resources: s.api_server.resources,
1749.                 },
1750.                 ()
1751.             );
1752.             let msg_ops = MessageOps {
1753.                 recv: None,
1754.                 send: host_result.get_Enabled_1().send,
1755.             };
1756.             let network_result = network().next_result(msg_ops, s.network);
1757. 
1758.             (host_result, network_result)
1759.         };
1760.         Action {
1761.             precondition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1762.                 &&& result(input, s).0.is_Enabled()
1763.                 &&& result(input, s).1.is_Enabled()
1764.             },
1765.             transition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1766.                 let (host_result, network_result) = result(input, s);
1767.                 (ClusterState {
1768.                     network: network_result.get_Enabled_0(),
1769.                     rpc_id_allocator: host_result.get_Enabled_1().rpc_id_allocator,
1770.                     ..s
1771.                 }, ())
1772.             },
1773.         }
1774.     }
