1776.     pub open spec fn controller_next(self) -> Action<ClusterState, (int, Option<Message>, Option<ObjectRef>), ()> {
1777.         Action {
1778.             precondition: |input: (int, Option<Message>, Option<ObjectRef>), s: ClusterState| {
1779.                 let controller_id = input.0;
1780.                 let chosen_action = self.chosen_controller_next(controller_id);
1781.                 (chosen_action.precondition)((input.1, input.2), s)
1782.             },
1783.             transition: |input: (int, Option<Message>, Option<ObjectRef>), s: ClusterState| {
1784.                 let controller_id = input.0;
1785.                 let chosen_action = self.chosen_controller_next(controller_id);
1786.                 (chosen_action.transition)((input.1, input.2), s)
1787.             },
1788.         }
1789.     }
