1791.     pub open spec fn chosen_controller_next(self, controller_id: int) -> Action<ClusterState, (Option<Message>, Option<ObjectRef>), ()> {
1792.         let result = |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1793.             let host_result = self.controller(controller_id).next_result(
1794.                 ControllerActionInput{recv: input.0, scheduled_cr_key: input.1, rpc_id_allocator: s.rpc_id_allocator},
1795.                 s.controller_and_externals[controller_id].controller
1796.             );
1797.             let msg_ops = MessageOps {
1798.                 recv: input.0,
1799.                 send: host_result.get_Enabled_1().send,
1800.             };
1801.             let network_result = network().next_result(msg_ops, s.network);
1802. 
1803.             (host_result, network_result)
1804.         };
1805.         Action {
1806.             precondition: |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1807.                 &&& self.controller_models.contains_key(controller_id)
1808.                 &&& input.1 is Some
1809.                 &&& received_msg_destined_for(input.0, HostId::Controller(controller_id, input.1->0))
1810.                 &&& result(input, s).0.is_Enabled()
1811.                 &&& result(input, s).1.is_Enabled()
1812.             },
1813.             transition: |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
