1815.                 let controller_and_external_state_prime = ControllerAndExternalState {
1816.                     controller: host_result.get_Enabled_0(),
1817.                     ..s.controller_and_externals[controller_id]
1818.                 };
1819.                 (ClusterState {
1820.                     controller_and_externals: s.controller_and_externals.insert(controller_id, controller_and_external_state_prime),
1821.                     network: network_result.get_Enabled_0(),
1822.                     rpc_id_allocator: host_result.get_Enabled_1().rpc_id_allocator,
1823.                     ..s
1824.                 }, ())
