2544.                         if filtered_pods.len() == desired_replicas {
2545.                             let state_prime = VReplicaSetReconcileState {
2546.                                 reconcile_step: VReplicaSetRecStepView::Done,
2547.                                 ..state
2548.                             };
2549.                             (state_prime, None)
2550.                         } else if filtered_pods.len() < desired_replicas {
2551.                             let diff =  desired_replicas - filtered_pods.len();
2552.                             let pod = make_pod(v_replica_set);
2553.                             let req = APIRequest::CreateRequest(CreateRequest {
2554.                                 namespace: namespace,
