2556.                             });
2557.                             let state_prime = VReplicaSetReconcileState {
2558.                                 reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2559.                                 ..state
2560.                             };
2561.                             (state_prime, Some(RequestView::KRequest(req)))
