2590.             let predicate1 = ( resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_CreateResponse() );
2591.             let predicate2 = resp_o.unwrap().get_KResponse_0().get_CreateResponse_0().res;
