2597.                     ..state
2598.                 };
2599.                 (state_prime, None)
2600.             } else {
2601.                 let pod = make_pod(v_replica_set);
2602.                 let req = APIRequest::CreateRequest(CreateRequest {
2603.                     namespace: namespace,
2604.                     obj: pod.marshal(),
2605.                 });
2606.                 let state_prime = VReplicaSetReconcileState {
2607.                     reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2608.                     ..state
2609.                 };
2610.                 (state_prime, Some(RequestView::KRequest(req)))
2611.             }
2612.         },
2613.         VReplicaSetRecStepView::AfterDeletePod(diff) => {
2614.             let diff = *diff;
2615.             let predicate1 = (resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_GetThenDeleteResponse());
2616.             let predicate2 = resp_o.unwrap().get_KResponse_0().get_GetThenDeleteResponse_0().res;
2617.                 
2618.             if !(predicate1 && predicate2 is Ok) {
2619.                 (error_state(state), None)
2620.             } else if diff == 0 {
2621.                 let state_prime = VReplicaSetReconcileState {
2622.                     reconcile_step: VReplicaSetRecStepView::Done,
2623.                     ..state
2624.                 };
2625.                 (state_prime, None)
2626.             } else {
