2843.             let action_input = (self.action_input)(witness_step, input);
2844.             ActionResult::Enabled((action.transition)(action_input, s).0, (action.transition)(action_input, s).1)
2845.         } else {
2846.             ActionResult::Disabled
2847.         }
2848.     }
