3156. #[verifier(inline)]
3157. pub open spec fn handle_create_request(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> (APIServerState, CreateResponse) {
3158.     if create_request_admission_check(installed_types, req, s) is Some {
3159.         // Creation fails.
3160.         (s, CreateResponse{res: Err(create_request_admission_check(installed_types, req, s)->0)})
3161.     } else {
3162.         let created_obj = DynamicObjectView {
3163.             kind: req.obj.kind,
3164.             metadata: ObjectMetaView {
3165.                 // Set name for new object if name is not provided, here we generate
3166.                 // a unique name. The uniqueness is guaranteed by generated_name_is_unique.
3167.                 name: if req.obj.metadata.name is Some {
3168.                     req.obj.metadata.name
3169.                 } else {
3170.                     Some(generate_name(s))
3171.                 },
3172.                 namespace: Some(req.namespace), // Set namespace for new object
3173.                 resource_version: Some(s.resource_version_counter), // Set rv for new object
3174.                 uid: Some(s.uid_counter), // Set uid for new object
3175.                 deletion_timestamp: None, // Unset deletion timestamp for new object
3176.                 ..req.obj.metadata
3177.             },
3178.             spec: req.obj.spec,
3179.             status: marshalled_default_status(req.obj.kind, installed_types), // Overwrite the status with the default one
3180.         };
3181.         if s.resources.contains_key(created_obj.object_ref()) {
3182.             // Note 1: You might find this branch redundant since we already have
3183.             // generated_name_is_unique which guarantees that the created_obj's
3184.             // key is different from any existing keys even if name was not provided.
3185.             // But we still add this branch just to avoid calling generated_name_is_unique
3186.             // when we want to show that create without a provided name does not override
3187.             // an existing object when writing proofs.
3188.             //
3189.             // Note 2: Adding this branch also means that if we want to prove the object
3190.             // is eventually created by a create request without the name provided,
3191.             // we need to explicitly call generated_name_is_unique to show that
3192.             // we do not fall into this branch.
3193.             (s, CreateResponse{res: Err(APIError::ObjectAlreadyExists)})
3194.         } else if created_object_validity_check(created_obj, installed_types) is Some {
3195.             // Creation fails.
3196.             (s, CreateResponse{res: Err(created_object_validity_check(created_obj, installed_types)->0)})
3197.         } else {
3198.             // Creation succeeds.
3199.             (APIServerState {
3200.                 resources: s.resources.insert(created_obj.object_ref(), created_obj),
3201.                 uid_counter: s.uid_counter + 1,
3202.                 resource_version_counter: s.resource_version_counter + 1,
3203.                 ..s
3204.             }, CreateResponse{res: Ok(created_obj)})
3205.         }
3206.     }
3207. }
