3209. pub open spec fn delete_request_admission_check(req: DeleteRequest, s: APIServerState) -> Option<APIError> {
3210.     if !s.resources.contains_key(req.key) {
3211.         // Deletion fails because the object does not exist
3212.         Some(APIError::ObjectNotFound)
3213.     } else if req.preconditions is Some {
3214.         let preconditions = req.preconditions->0;
3215.         if preconditions.uid is Some && preconditions.uid != s.resources[req.key].metadata.uid {
3216.             // Deletion fails because the uid of the object does not match the uid in the precondition
3217.             Some(APIError::Conflict)
3218.         } else if preconditions.resource_version is Some && preconditions.resource_version != s.resources[req.key].metadata.resource_version {
3219.             // Deletion fails because the resource version of the object does not match the resource version in the precondition
3220.             Some(APIError::Conflict)
3221.         } else {
3222.             None
3223.         }
3224.     } else {
3225.         None
3226.     }
3227. }
